static const vqeaf_sound_clip_t clips[VQEAF_SOUND_COUNT] = {
    { vqeaf_sound_tap, 5028 },
    { vqeaf_sound_drop, 10538 },
    { vqeaf_sound_navigate, 10532 },
    { vqeaf_sound_notify, 16034 },
    { vqeaf_sound_capture, 7778 },
    { vqeaf_sound_record, 16067 },
    { vqeaf_sound_warning, 21522 },
    { vqeaf_sound_charge, 21561 },
};

const vqeaf_sound_clip_t *vqeaf_sound_clip(vqeaf_sound_event_t event)
{
    if((unsigned int)event >= VQEAF_SOUND_COUNT) return NULL;
    return &clips[event];
}
